const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([104.238631, 40.923221]);
  const region = center.buffer(50000); // 50km radius

  // Define time periods for comparison
  const period1 = ['2019-02-01', '2019-02-28']; // Feb 2019
  const period2 = ['2020-02-01', '2020-02-29']; // Feb 2020

  // 2. Data Acquisition - Using Sentinel-5P Aerosol Index as PM2.5 proxy
  const getCollection = (startDate, endDate) => {
    return ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
      .filterDate(startDate, endDate)
      .filterBounds(region)
      .select('absorbing_aerosol_index');
  };

  const col1 = getCollection(period1[0], period1[1]);
  const col2 = getCollection(period2[0], period2[1]);

  // Check collection sizes
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Feb 2019 Images: ${size1}`);
  console.log(`Feb 2020 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean images and statistics
  const mean1 = col1.mean();
  const mean2 = col2.mean();

  // Calculate pixel counts and mean values
  const stats1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const val1 = stats1.get('absorbing_aerosol_index_mean').getInfo();
  const count1 = stats1.get('absorbing_aerosol_index_count').getInfo();
  const val2 = stats2.get('absorbing_aerosol_index_mean').getInfo();
  const count2 = stats2.get('absorbing_aerosol_index_count').getInfo();

  console.log(`Feb 2019: AI=${val1?.toFixed(3)}, Pixels=${count1}`);
  console.log(`Feb 2020: AI=${val2?.toFixed(3)}, Pixels=${count2}`);

  // 4. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (val1 === null || val2 === null || !isFinite(val1) || !isFinite(val2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare PM2.5 proxy values (higher aerosol index = higher PM2.5)
  if (val2 > val1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
